// resolverPedido (secao 2.5)
// entrada: { pedido, catalogo, condados, zips, config, autorizado, texto_origem, hoje, agora,
//            certificado_revenda (coluna do rascunho, na correcao), logo_b64_len, webhook_teste }
// saida: { status, faltando[], faltando_det[], avisos[], avisos_det[], alertas[], calculo,
//          pedido_guardado, certificado_revenda, texto_origem, idioma, ja_anotei }
// ---------------------------------------------------------------------------------------------------

function resolverPedido(e) {
  var pedido = clonar(e.pedido || {}) || {};
  var config = e.config || {};
  var catalogo = Array.isArray(e.catalogo) ? e.catalogo : [];
  var condados = Array.isArray(e.condados) ? e.condados : [];
  var zips = Array.isArray(e.zips) ? e.zips : [];
  var autorizado = e.autorizado || {};
  var hoje = isoData(e.hoje);
  var textoOrigem = String(e.texto_origem || '');
  var idioma = (pedido.idioma === 'en' || pedido.idioma === 'es') ? pedido.idioma : 'pt';
  var faltas = [], avisos = [], alertas = [];
  function falta(codigo, p, linha) { faltas.push({ codigo: codigo, linha: linha || null, pt: txt(codigo, 'pt', p), en: txt(codigo, 'en', p), es: txt(codigo, 'es', p) }); }
  function avisa(codigo, p) {
    var a = { codigo: codigo, pt: txt('aviso_' + codigo, 'pt', p), en: txt('aviso_' + codigo, 'en', p), es: txt('aviso_' + codigo, 'es', p) };
    if (!avisos.some(function (x) { return x.pt === a.pt; })) avisos.push(a);
  }

  // ---- teste real (serie HP-I-T): so admin
  var testeReal = pedido.teste_real === true;
  if (testeReal && autorizado.papel !== 'admin') { testeReal = false; avisa('teste_ignorado'); }

  // ---- cliente
  var cli = pedido.cliente || {};
  var cliente = { nome: String(cli.nome || '').trim(), empresa: String(cli.empresa || '').trim(), email: String(cli.email || '').trim(), telefone: String(cli.telefone || '').trim() };
  if (!cliente.nome) falta('cliente_nome');

  // ---- entrega e condado (sempre pelo ZIP)
  var ent = pedido.entrega || {};
  var entrega = { endereco: String(ent.endereco || '').trim(), cidade: String(ent.cidade || '').trim(), estado: 'FL', zip: '' };
  // estado: vazio, FL, Fla., Florida, Flórida, "Florida, USA" passam (a barreira real e a faixa de ZIP abaixo)
  var estado = norm(ent.estado || '');
  var foraFl = !!estado && !/^(fl|fla|florida)( usa| us)?$/.test(estado);
  if (foraFl) falta('fora_fl');
  // etapa 5 (pedido minimo): rua e ZIP sao opcionais; basta a cidade (ou o condado). ZIP mal escrito ainda e perguntado.
  var zipBruto = String(ent.zip == null ? '' : ent.zip).trim();
  var zipM = /^\s*(\d{5})(-\d{4})?\s*$/.exec(zipBruto);
  var condInf0 = tem(ent, 'condado') ? String(ent.condado || '').trim() : '';
  if (!entrega.cidade && !zipM && !condInf0) falta('entrega_cidade');
  if (zipBruto && !zipM) falta('entrega_zip');
  if (zipM) {
    entrega.zip = zipM[1];
    // ZIP da Florida: 32004 a 34997. Fora da faixa bloqueia antes de qualquer regra de condado,
    // inclusive quando a pessoa informou um condado (a v1 nao emite fora da Florida)
    var zipN = parseInt(entrega.zip, 10);
    if ((zipN < 32004 || zipN > 34997) && !foraFl) { foraFl = true; falta('fora_fl'); }
  }
  if (entrega.endereco) {
    var nEnd = norm(entrega.endereco);
