      if (condInf && normCondado(condInf) !== normCondado(condado)) { falta('condado_diverge_zip', { x: condInf, zip: entrega.zip, y: condado }); condado = null; }
    } else if (zipRow && zipRow.condados.length > 1) {
      var m = zipRow.condados.filter(function (c) { return condInf && normCondado(c) === normCondado(condInf); })[0];
      if (m) { condado = m; condadoFonte = 'zip_confirmado'; }
