      var outros = condados.filter(function (r) { return (r.cidades || []).indexOf(nc) >= 0; }).map(function (r) { return r.condado; })
        .filter(function (c, i, a) { return a.indexOf(c) === i; });
      var zipLista = zipRow && (zipRow.cidades || []).indexOf(nc) >= 0;
      if (outros.length && outros.indexOf(condado) < 0 && !zipLista) {
        if (condInf && normCondado(condInf) === normCondado(condado)) avisa('cidade_confirmada', { cidade: entrega.cidade, outro: outros[0], zip: entrega.zip, condado: condado });
        else { falta('cidade_zip_divergem', { cidade: entrega.cidade, outro: outros[0], zip: entrega.zip, condado: condado }); condadoRow = null; }
      }
    }
  }

  // ---- sem ZIP (etapa 5): condado pela cidade (hz_condados.cidades) ou pelo condado que a pessoa disse
  if (!entrega.zip && !zipBruto && !foraFl && (entrega.cidade || condInf0)) {
    var ncid = norm(entrega.cidade).replace(/\s+(fl|fla|florida)(\s+usa?)?$/, '').replace(/^city of\s+/, '').trim();
    var candC = !ncid ? [] : condados.filter(function (r) { return (r.cidades || []).indexOf(ncid) >= 0; }).map(function (r) { return r.condado; })
      .filter(function (c, i, a) { return a.indexOf(c) === i; });
    var condInfC = condInf0 ? canonCondado(condados, condInf0) : '';
    // a pessoa disse o condado: vale o que ela disse
    if (condInfC) { condado = condInfC; condadoFonte = 'informado'; }
    else if (candC.length === 1) { condado = candC[0]; condadoFonte = 'cidade'; avisa('condado_cidade', { cidade: entrega.cidade, condado: candC[0] }); }
    else if (candC.length > 1) falta('cidade_varios_condados', { cidade: entrega.cidade, lista: function (l) { return listaE(candC, l); } });
    else falta('cidade_desconhecida', { cidade: entrega.cidade });
    if (condado) {
      condadoRow = condados.filter(function (r) {
        return vigente(r, hoje) && (normCondado(r.condado) === normCondado(condado) || (r.apelidos || []).some(function (a) { return normCondado(a) === normCondado(condado); }));
      })[0] || null;
      if (!condadoRow) { falta('condado_sem_aliquota', { x: condado }); }
      else condado = condadoRow.condado;
    }
  }

  // ---- itens
  var itensIn = Array.isArray(pedido.itens) ? pedido.itens : [];
  var maxLinhas = cfgInt(config.max_linhas, 1, 100, 25);
  var linhas = [];
  if (itensIn.length > maxLinhas) falta('itens_demais', { max: maxLinhas });
  else {
    var produtos = indexarCatalogo(catalogo);
    itensIn.forEach(function (it, idx) {
      var n = idx + 1;
      it = it || {};
      var nome = String(it.produto || '').trim();
      var achado = acharProduto(produtos, nome);
      if (achado.erro === 'nao') {
        var parL = achado.parecidos.slice();
        var par = !parL.length ? '' : function (l) { return (l === 'en' ? '; similar: ' : '; parecidos: ') + parL.join(', '); };
        falta('item_nao_encontrado', { x: nome || '?', parecidos: par }, n); return;
      }
      if (achado.erro === 'ambiguo') { falta('item_ambiguo', { x: nome, opcoes: (function (op) { return function (l) { return listaOu(op, l); }; })(achado.opcoes) }, n); return; }
      var p = achado.produto;
      var ativos = p.rows.filter(function (r) { return r.ativo !== false; });
      var tams = TAMANHOS.filter(function (t) { return ativos.some(function (r) { return r.tamanho === t; }); });
      var ok = true, tam = null, acab = null;
      var tamInf = String(it.tamanho == null ? '' : it.tamanho).trim();
      if (!tams.length) {
        if (tamInf) { var h0 = numOuNulo((ativos[0] || p.rows[0]).altura_in); falta('tamanho_unico', { produto: p.produto, h: h0 !== null ? fracIn(h0) + ' in' : '?' }, n); ok = false; }
      } else if (!tamInf) { falta('tamanho', { produto: p.produto, opcoes: (function (op) { return function (l) { return listaOu(op, l); }; })(tams) }, n); ok = false; }
      else { tam = normTamanho(tamInf); if (!tam || tams.indexOf(tam) < 0) { falta('tamanho_invalido', { produto: p.produto, x: tamInf, opcoes: (function (op) { return function (l) { return listaOu(op, l); }; })(tams) }, n); ok = false; } }
      var acabInf = String(it.acabamento == null ? '' : it.acabamento).trim();
      if (p.colecao === 'Signature') {
        if (!acabInf) { falta('acabamento', { produto: p.produto }, n); ok = false; }
        else { acab = normAcabamento(acabInf); if (!acab) { falta('acabamento_invalido', { x: acabInf }, n); ok = false; } }
      } else if (acabInf) { falta('sem_acabamento', { produto: p.produto, x: acabInf }, n); ok = false; }
      var q = parseQtd(it.qtd);
      if (q === null) { falta('qtd', { produto: p.produto }, n); ok = false; }
      if (!ok) return;
      var row = ativos.filter(function (r) { return (r.tamanho || null) === tam && (r.acabamento || null) === acab; })[0];
      if (!row) { falta('variante_inexistente', { produto: p.produto, tamanho: tam || '', acabamento: acab || '' }, n); return; }
      var tamTxt = tam ? ' ' + tam : '';

      // preco: manual > (aprovado, se exigido) > Shopify
      var shop = intOuNulo(row.preco_shopify_cents), aprov = intOuNulo(row.preco_aprovado_cents);
      var unit = null, origem = null;
      if (tem(it, 'preco_unit_manual')) {
        var mm = parseDinheiro(it.preco_unit_manual);
        if (mm === null) falta('preco', { produto: p.produto, x: String(it.preco_unit_manual) }, n);
        else if (mm === 0) falta('preco_zero', { produto: p.produto }, n); // zero digitado por engano nao vira invoice
        else {
          unit = mm; origem = (shop !== null && mm === shop) ? 'confirmado_na_conversa' : 'manual';
          if (origem === 'manual') {
            avisa('preco_manual', { n: n, produto: p.produto + tamTxt, usado: fmtUSD(mm), shopify: shop === null ? '-' : fmtUSD(shop) });
            if (autorizado.papel !== 'admin' && cfgBool(config.avisar_thiago_preco_manual)) {
              alertas.push('Horizon: ' + (autorizado.nome || 'alguém') + ' pôs preço manual em ' + row.sku + ': ' + fmtUSD(mm) + ' (Shopify ' + (shop === null ? '-' : fmtUSD(shop)) + ').');
            }
          }
        }
      } else if (cfgBool(config.exigir_preco_aprovado)) {
        if (row.preco_status === 'aprovado' && shop !== null && shop === aprov) { unit = shop; origem = 'aprovado'; }
        else if (row.preco_status === 'aprovado') falta('preco_divergente', { sku: row.sku, a: shop === null ? '-' : fmtUSD(shop), b: aprov === null ? '-' : fmtUSD(aprov) }, n);
        else falta('preco_a_confirmar', { produto: p.produto, tam: tamTxt, preco: shop === null ? '-' : fmtUSD(shop), valor: shop === null ? '' : String(shop / 100) }, n);
      } else if (shop === null) falta('preco_ausente', { produto: p.produto, tam: tamTxt }, n);
      else { unit = shop; origem = (row.preco_status === 'aprovado' && aprov === shop) ? 'aprovado' : 'shopify'; }

      // desconto da linha
      var descCents = 0, descBp = null;
      if (unit !== null) {
        var bruto = q * unit;
        var onde = (function (nn) { return function (l) { return (l === 'en' ? ' on item ' : l === 'es' ? ' del ítem ' : ' do item ') + nn; }; })(n);
        if (tem(it, 'desconto_pct') && tem(it, 'desconto_valor')) falta('desconto', { onde: onde, base: fmtUSD(bruto) }, n);
        else if (tem(it, 'desconto_pct')) {
          descBp = parsePct(it.desconto_pct);
          if (descBp === null) falta('desconto', { onde: onde, base: fmtUSD(bruto) }, n); else descCents = arred(bruto * descBp, 10000);
        } else if (tem(it, 'desconto_valor')) {
          var dv = parseDinheiro(it.desconto_valor);
          if (dv === null || dv <= 0 || dv >= bruto) falta('desconto', { onde: onde, base: fmtUSD(bruto) }, n); else descCents = dv;
        }
      }

      // medidas (por variante; nunca as de outro tamanho)
      var medTxt = medidasTexto(row);
      if (medTxt === null) avisa('medidas', { n: n, produto: p.produto, tam: tamTxt });

      // foto: so a da variante; a do modelo so com foto_modelo_permitida = 'true'
      var fotoOrigem = row.foto_origem || 'variante';
      var temFoto = row.foto_status === 'ok' && !!row.foto_url && (Number(row.foto_b64_len) || 0) > 0;
      if (temFoto && fotoOrigem === 'modelo' && !cfgBool(config.foto_modelo_permitida)) temFoto = false;
      if (!temFoto) {
        if (p.colecao === 'Signature') avisa('foto_acab', { n: n, produto: p.produto, acabamento: acab });
        else avisa('foto', { n: n, produto: p.produto });
      } else if (fotoOrigem === 'modelo') avisa('foto_modelo', { n: n, produto: p.produto, acabamento: acab });

      linhas.push({
        linha: n, sku: row.sku, produto: p.produto, colecao: p.colecao, tamanho: tam, acabamento: acab, qtd: q,
        preco_unit_cents: unit, preco_shopify_cents: shop, preco_origem: origem,
        desconto_pct_bp: descBp, desconto_cents: descCents, total_cents: unit === null ? null : q * unit - descCents,
        medidas: { altura_in: numOuNulo(row.altura_in), largura_in: numOuNulo(row.largura_in), boca_in: numOuNulo(row.boca_in), base_in: numOuNulo(row.base_in), peso_lb: numOuNulo(row.peso_lb) },
        medidas_txt: medTxt,
        foto: temFoto ? { url: row.foto_url, sha256: row.foto_sha256 || null, origem: fotoOrigem, b64_len: Number(row.foto_b64_len) || 0 } : null
      });
    });
    if (!itensIn.length && !faltas.some(function (f) { return f.codigo === 'item_nao_encontrado'; })) falta('item_nao_encontrado', { x: function (l) { return l === 'en' ? '(no pieces)' : l === 'es' ? '(ninguna pieza)' : '(nenhuma peça)'; }, parecidos: '' });
  }

  // ---- tamanho estimado do PDF (fotos unicas + logo + 60 KB)
  var unicas = {}, est = 60000 + Math.round((Number(e.logo_b64_len) || 0) * 3 / 4);
  linhas.forEach(function (l) { if (l.foto) { var k = l.foto.sha256 || l.foto.url; if (!unicas[k]) { unicas[k] = 1; est += Math.round(l.foto.b64_len * 3 / 4); } } });
  if (est > cfgInt(config.max_pdf_bytes, 100000, 15000000, 5000000)) falta('pdf_grande');

  // ---- desconto no total (sobre as pecas, depois dos descontos de linha)
  var pecasLinhas = linhas.reduce(function (a, l) { return a + (l.total_cents || 0); }, 0);
  var descTotal = null;
  var ondeT = function (l) { return l === 'en' ? ' on the total' : l === 'es' ? ' en el total' : ' no total'; };
  if (tem(pedido, 'desconto_pct') && tem(pedido, 'desconto_valor')) falta('desconto', { onde: ondeT, base: fmtUSD(pecasLinhas) });
  else if (tem(pedido, 'desconto_pct')) {
    var bpT = parsePct(pedido.desconto_pct);
    if (bpT === null) falta('desconto', { onde: ondeT, base: fmtUSD(pecasLinhas) });
    else descTotal = { tipo: 'pct', pct_bp: bpT, cents: arred(pecasLinhas * bpT, 10000) };
  } else if (tem(pedido, 'desconto_valor')) {
    var dvT = parseDinheiro(pedido.desconto_valor);
    if (dvT === null || dvT <= 0 || (linhas.length && dvT >= pecasLinhas)) falta('desconto', { onde: ondeT, base: fmtUSD(pecasLinhas) });
    else descTotal = { tipo: 'valor', pct_bp: null, cents: dvT };
  }

  // ---- frete (v1.2, decisao 4 de 25/10): valor informado vale sempre (0 = gratis); "a cotar"/"a combinar" ou ausente
  // vira CORTESIA quando as pecas depois dos descontos passam do limite e a entrega e na Florida; senao, como na v1.1
  var frete = null;
  var fIn = pedido.frete;
  var acimaCortesia = cfgInt(config.frete_cortesia_acima_cents, 0, 1000000000, 500000); // '0' desliga a regra
  var pecasDepoisDesconto = pecasLinhas - (descTotal ? descTotal.cents : 0);
  var cortesia = acimaCortesia > 0 && !foraFl && linhas.length > 0 && linhas.length === itensIn.length && pecasDepoisDesconto > acimaCortesia;
  var freteAusente = (fIn === undefined || fIn === null || fIn === '');
  var freteACotar = typeof fIn === 'string' && /^(a cotar|a combinar|to be quoted|tbq|tbd|quote|a calcular)$/.test(norm(fIn).replace(/_/g, ' '));
  if (freteAusente || freteACotar) {
    if (cortesia) frete = { status: 'cortesia', cents: 0 };
    else frete = { status: 'a_cotar', cents: 0 }; // etapa 5: ausente ou "a cotar" = a combinar (fora do total), sem perguntar
  } else { var fc = parseDinheiro(fIn); if (fc === null) falta('frete'); else frete = { status: fc === 0 ? 'gratis' : 'valor', cents: fc }; }
  if (frete) frete.tributavel = cfgBool(config.frete_tributavel);
  if (frete && frete.status === 'a_cotar') avisa('frete_a_cotar');
  if (frete && frete.status === 'cortesia') avisa('frete_cortesia', { acima: fmtUSD(acimaCortesia) });

  // ---- montagem / instalacao (tributavel)
  var montagem = 0;
  if (tem(pedido, 'montagem')) { var mc = parseDinheiro(pedido.montagem); if (mc === null) falta('montagem'); else montagem = mc; }

  // ---- revenda
  var rev = pedido.revenda || {};
  var isento = false, certificado = null, certValidade = null;
  if (rev.isento === true) {
    var certIn = e.certificado_revenda || rev.certificado || '';
    if (/^\*\*\*/.test(String(certIn))) certIn = e.certificado_revenda || '';
    var dig = String(certIn).replace(/[\s-]/g, '');
    var okRev = true;
    if (!/^\d{10,16}$/.test(dig)) { falta('revenda_certificado'); okRev = false; } else certificado = String(certIn).trim();
    var val = String(rev.validade == null ? '' : rev.validade).trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(val)) { falta('revenda_validade'); okRev = false; }
    else if (val < hoje) { falta('revenda_vencido', { data: function (l) { return l === 'en' ? fmtData(val) : fmtDataBR(val); } }); okRev = false; }
    else certValidade = val;
    if (rev.copia_arquivada !== true) { falta('revenda_copia'); okRev = false; }
    isento = okRev;
  }

  // ---- link de pagamento (https, host da loja, escrito literalmente na mensagem)
  var link = null;
  if (tem(pedido, 'link_pagamento')) {
    var lk = String(pedido.link_pagamento).trim(), okLink = false;
    // host por regex (sem depender do URL global do sandbox); "usuario@host" e porta estranha nao passam
    var mh = /^https:\/\/([a-z0-9.-]+)(?::\d{1,5})?(?:[\/?#]|$)/i.exec(lk);
    if (mh && textoOrigem.indexOf(lk) >= 0) {
      var host = mh[1].toLowerCase();
      okLink = String(config.link_pagamento_hosts || '').split(',').map(function (h) { return h.trim().toLowerCase(); }).filter(Boolean)
        .some(function (h) { return h.indexOf('*.') === 0 ? (host.slice(-(h.length - 1)) === h.slice(1) && host.length > h.length - 1) : host === h; });
    }
    if (okLink) link = lk; else falta('link_pagamento_invalido');
  }

  // ---- validade
  var padraoDias = cfgInt(config.validade_dias, 1, 60, 15), dias = padraoDias;
  if (tem(pedido, 'validade_dias')) { var vd = parseInt(pedido.validade_dias, 10); if (Number.isInteger(vd) && vd >= 1 && vd <= 60 && String(vd) === String(pedido.validade_dias).trim()) dias = vd; else avisa('validade', { dias: padraoDias }); }

  // ---- avisos fixos
  if ((condadoRow && condadoRow.conferido_contador !== true) || (zipRow && zipRow.conferido !== true)) avisa('contador');
  if (frete && frete.status === 'valor' && frete.cents > 0 && !frete.tributavel && !String(config.termos_frete_titulo || '').trim()) avisa('frete_clausula');
  if (!link && !String(config.pagamento_zelle || '').trim() && !String(config.pagamento_wire || '').trim() && !String(config.pagamento_cartao_link || '').trim()) avisa('sem_pagamento');
  // texto do contador: na invoice real (fora da serie HP-I-T e do webhook de teste) os colchetes nunca vao ao PDF.
  // Sem o texto, ou bloqueia (bloquear_sem_texto_contador = 'true') ou a linha sai omitida, com aviso.
  var semTextoContador = !String(config.termos_frete_titulo || '').trim() || !String(config.termos_condicoes || '').trim();
  if (semTextoContador && !testeReal && e.webhook_teste !== true) {
    if (cfgBool(config.bloquear_sem_texto_contador)) falta('texto_contador');
    else avisa('contador_omitido');
  }
  if (e.agora) {
    var maxSync = catalogo.reduce(function (m, r) { var t = r.sincronizado_em ? Date.parse(r.sincronizado_em) : NaN; return Number.isFinite(t) && t > m ? t : m; }, 0);
    if (!maxSync || Date.parse(e.agora) - maxSync > 48 * 3600 * 1000) avisa('catalogo_velho');
  }

  // ---- pedido guardado e texto de origem com o certificado mascarado
  var pedidoGuardado = clonar(pedido);
  var certParaMascara = certificado || (rev.certificado && !/^\*\*\*/.test(String(rev.certificado)) ? rev.certificado : null);
  if (pedidoGuardado.revenda && pedidoGuardado.revenda.certificado && certParaMascara) pedidoGuardado.revenda.certificado = mascararCert(certParaMascara);
  var textoMascarado = certParaMascara ? mascararTexto(textoOrigem, certParaMascara) : textoOrigem;

  var codigos = [];
  faltas.forEach(function (f) { if (codigos.indexOf(f.codigo) < 0) codigos.push(f.codigo); });
  var status = faltas.length ? 'incompleto' : 'aguardando_confirmacao';

  var calculo = null;
  if (!faltas.length) {
    var estBp = cfgInt(config.estadual_bp, 0, 1000, 600);
    var totais = calcularTotais({
      itens: linhas.map(function (l) { return { qtd: l.qtd, preco_unit_cents: l.preco_unit_cents, desconto_cents: l.desconto_cents }; }),
      desconto_total_cents: descTotal ? descTotal.cents : 0, montagem_cents: montagem, frete: frete,
      isento: isento, estadual_bp: estBp, sobretaxa_bp: condadoRow.sobretaxa_bp
    });
    calculo = {
      versao: 1, idioma: idioma, teste_real: testeReal,
      cliente: cliente, entrega: entrega,
      condado: { nome: condadoRow.condado, sobretaxa_bp: condadoRow.sobretaxa_bp, estadual_bp: estBp, fonte: condadoFonte, tabela_fonte: condadoRow.fonte || null, conferido: condadoRow.conferido_contador === true && (!zipRow || zipRow.conferido === true) },
      isento: isento,
      revenda: isento ? { ultimos4: ultimos4(certificado), mascara: mascararCert(certificado), validade: certValidade } : null,
      itens: linhas, desconto_total: descTotal, frete: frete, montagem_cents: montagem,
      validade_dias: dias, link_pagamento: link, observacoes: String(pedido.observacoes || '').trim(),
      totais: totais
    };
  }
  return {
    status: status, faltando: codigos, faltando_det: faltas,
    avisos: avisos.map(function (a) { return a[idioma]; }), avisos_det: avisos, alertas: alertas,
    calculo: calculo, pedido_guardado: pedidoGuardado, certificado_revenda: isento ? certificado : (certificado || null),
    texto_origem: textoMascarado, idioma: idioma, teste_real: testeReal,
    ja_anotei: { cliente: cliente.nome || null, n_itens: itensIn.length, cidade: entrega.cidade || null, zip: entrega.zip || null }
  };
}

// No "sim": o certificado ainda vale hoje e cada SKU continua ativo? (Montar Numeracao, T36)
function revalidarParaNumerar(c, catalogo, hoje, idioma) {
  hoje = isoData(hoje);
  if (c.isento && c.revenda && c.revenda.validade && c.revenda.validade < hoje) {
    return { ok: false, motivo: (idioma === 'en' ? 'the resale certificate expired on ' + fmtData(c.revenda.validade) : idioma === 'es' ? 'el certificado de reventa venció el ' + fmtDataBR(c.revenda.validade) : 'o certificado de revenda venceu em ' + fmtDataBR(c.revenda.validade)) };
  }
  for (var i = 0; i < c.itens.length; i++) {
    var sku = c.itens[i].sku;
    var row = (catalogo || []).filter(function (r) { return r.sku === sku; })[0];
    if (!row || row.ativo === false) return { ok: false, motivo: (idioma === 'en' ? sku + ' left the catalog' : idioma === 'es' ? 'el ' + sku + ' salió del catálogo' : 'o ' + sku + ' saiu do catálogo') };
  }
  return { ok: true, motivo: null };
}

// ---------------------------------------------------------------------------------------------------
// juntarPedido (secao 2.5.1): a IA manda so o que mudou; junta com o pedido guardado do rascunho antigo
// ---------------------------------------------------------------------------------------------------

function juntarPedido(antigo, certificadoAntigo, patch, idRascunho) {
  var novo = clonar(antigo || {}) || {};
  patch = patch || {};
  var faltas = [], camposRemovidos = [];
  function has(o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); }
  // um tipo de desconto novo (pct ou valor) apaga o outro, a menos que o patch traga os dois
  function trocarTipoDesconto(alvo, p) {
    var vemPct = tem(p, 'desconto_pct'), vemValor = tem(p, 'desconto_valor');
    if (vemPct && !has(p, 'desconto_valor')) delete alvo.desconto_valor;
    if (vemValor && !has(p, 'desconto_pct')) delete alvo.desconto_pct;
  }
  trocarTipoDesconto(novo, patch);
  ['idioma', 'frete', 'montagem', 'validade_dias', 'link_pagamento', 'observacoes', 'desconto_pct', 'desconto_valor', 'teste_real'].forEach(function (k) {
    if (!has(patch, k)) return;
    if (patch[k] === '' || patch[k] === null) { if (has(novo, k)) camposRemovidos.push(k); delete novo[k]; }
    else novo[k] = patch[k];
  });
  ['cliente', 'entrega', 'revenda'].forEach(function (obj) {
    var p = patch[obj];
    if (!p || typeof p !== 'object') return;
    var alvo = (novo[obj] && typeof novo[obj] === 'object') ? novo[obj] : {};
