      ' >> /Contents ' + cNum + ' 0 R >>'));
  });
  objects[pagesIdx] = '<< /Type /Pages /Count ' + pageNums.length + ' /Kids [' + pageNums.map(function (n) { return n + ' 0 R'; }).join(' ') + '] >>';
  var chunks = [], offset = 0;
  function push(x) { var b = Buffer.isBuffer(x) ? x : Buffer.from(x, 'latin1'); chunks.push(b); offset += b.length; }
  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  var xref = [0];
  objects.forEach(function (body, i) {
    xref.push(offset);
    push((i + 1) + ' 0 obj\n');
    if (typeof body === 'string') push(body + '\nendobj\n');
    else { push(body.dict + '\nstream\n'); push(body.stream); push('\nendstream\nendobj\n'); }
  });
  var xrefOff = offset, count = objects.length + 1;
  push('xref\n0 ' + count + '\n');
  push('0000000000 65535 f \n');
  for (var j = 1; j < count; j++) push(('0000000000' + xref[j]).slice(-10) + ' 00000 n \n');
  push('trailer\n<< /Size ' + count + ' /Root 1 0 R >>\nstartxref\n' + xrefOff + '\n%%EOF\n');
  return Buffer.concat(chunks);
}

// rotulo em caixa alta com tracking (usado nos tres designs)
function rotulo(pg, s, x, baseline, o) {
  o = o || {};
  return drawText(pg, String(s).toUpperCase(), { x: x, baseline: baseline, font: o.font || BD, size: o.size || 7, color: o.color || COR.ochre, tc: o.tc === undefined ? 0.9 : o.tc, align: o.align, maxWidth: o.maxWidth, shrink: !!o.maxWidth });
}

// Coluna de campos (BILL TO / DELIVER TO) parametrizada; entradas: [{campo, texto, linhas?}], vazias omitidas,
// ate 5 linhas; devolve os campos cortados com "…" (o Montar Rascunho avisa no resumo antes de numerar).
// o: {x, w, yIni (baseline da 1a linha), lineH, size, sizeMin, cor, corNegrito, primeiraNegrito, maxLinhas}
function colunaCampos(pg, entradas, o) {
  var usadas = 0, cortes = [], maxL5 = o.maxLinhas || 5, size0 = o.size || 9, sizeMin = o.sizeMin || 7.5;
  (entradas || []).filter(function (en) { return en && en.texto; }).forEach(function (en, i) {
    var font = (o.primeiraNegrito && i === 0) ? BD : RG, cor = (o.primeiraNegrito && i === 0 && o.corNegrito) ? o.corNegrito : o.cor;
    if (usadas >= maxL5) { cortes.push(en.campo); return; }
    var maxL = Math.min(en.linhas || 1, maxL5 - usadas);
    if (maxL > 1) {
      var size = size0, q = quebrar(en.texto, font, size0, o.w, 0, true), cortou = false;
      if (q.linhas.length > maxL) { size = sizeMin; q = quebrar(en.texto, font, sizeMin, o.w, 0, true); }
      if (q.linhas.length > maxL) { q = quebrar(en.texto, font, sizeMin, o.w, maxL, false); cortou = true; }
      q.linhas.forEach(function (l) { if (pg) pg.add(textOpTc(l, font, size, cor, o.x, PAGE_H - (o.yIni + usadas * o.lineH), 0)); usadas++; });
      if (cortou) cortes.push(en.campo);
    } else {
      var r = drawText(pg, en.texto, { x: o.x, baseline: o.yIni + usadas * o.lineH, font: font, size: size0, color: cor, maxWidth: o.w, shrink: true, minSize: sizeMin });
      if (r.cortado) cortes.push(en.campo);
      usadas++;
    }
  });
  return { cortes: cortes, linhas: usadas };
}
// pares rotulo/valor (INVOICE DETAILS); o: {x, w, wRot, yIni, lineH, size, sizeMin, corRot, cor}
function colunaDetalhes(pg, linhas, o) {
  var cortes = [], size0 = o.size || 9, sizeMin = o.sizeMin || 7.5;
  (linhas || []).slice(0, o.maxLinhas || 5).forEach(function (l, i) {
    drawText(pg, l[0], { x: o.x, baseline: o.yIni + i * o.lineH, font: RG, size: size0, color: o.corRot, maxWidth: o.wRot - 6, shrink: true, minSize: sizeMin });
    var r = drawText(pg, l[1], { x: o.x + o.wRot, baseline: o.yIni + i * o.lineH, font: o.valorNegrito ? BD : RG, size: size0, color: o.cor, maxWidth: o.w - o.wRot, shrink: true, minSize: sizeMin });
    if (r.cortado) cortes.push(l[0]);
  });
  return { cortes: cortes, linhas: Math.min((linhas || []).length, o.maxLinhas || 5) };
}
// empresa_linha: a parte antes do primeiro "·" em negrito; devolve a largura usada
function linhaEmpresa(pg, texto, o) {
  var emp = String(texto || ''), k = emp.indexOf('·');
  var negrito = k > 0 ? emp.slice(0, k).trim() : emp, resto = k > 0 ? ' ' + emp.slice(k) : '';
  var size = o.size, wTot = textWidth(negrito, BD, size) + textWidth(resto, RG, size);
  if (wTot > o.maxWidth) size = Math.max(o.minSize || 6.5, size * o.maxWidth / wTot);
  var wN = drawText(pg, negrito, { x: o.x, baseline: o.baseline, font: BD, size: size, color: o.color }).largura;
  drawText(pg, resto, { x: o.x + wN, baseline: o.baseline, font: RG, size: size, color: o.corResto || o.color, maxWidth: o.maxWidth - wN });
  return Math.min(wTot, o.maxWidth);
}
// paginacao comum: linhas (com .h) empilhadas a partir de yIni1 (pag 1) / yIniN (continuacao) ate corpoFim;
// o fechamento (hF) nunca se divide. Devolve {plano:[{pag,y,r}], comTabela:[], pagFech, yC, N}
function paginar(linhas, o, hF) {
  var plano = [], pag = 0, y = o.yIni1, comTabela = [true];
  linhas.forEach(function (r) {
    if (y + r.h > o.corpoFim) { pag++; y = o.yIniN; comTabela[pag] = true; }
    plano.push({ pag: pag, y: y, r: r }); y += r.h;
  });
  var yC;
  if (y + o.gapFech + hF > o.corpoFim) { pag++; yC = o.yFechN; } else yC = y + o.gapFech;
  return { plano: plano, comTabela: comTabela, pagFech: pag, yC: yC, N: pag + 1 };
}

// ---------------------------------------------------------------------------
// DIRECAO A2 - EDITORIAL (A) + GRADE DE MEDIDAS (B)  -  versao final escolhida pelo Thiago em 25/10/2026
// Faixa Deep Moss sangrada no topo com o logo em Sand; colunas BILL TO / DELIVER TO / DETAILS abertas (so um
// filete fino sob o rotulo); tabela com cabecalho em caixa alta tracked e filete; fotos quadradas de 80 pt
// com o selo "Manufacturer photo" como legenda abaixo (a foto inteira fica para a peca); as medidas saem na
// grade HEIGHT / WIDTH / OPENING / BASE / WEIGHT (da direcao B) dentro da linha da peca; quando a variante
// nao tem medidas padrao ("Dimensions on request", Ori "Set of 2 · ...") cai para o texto corrido; totais em
// caixa Sand; rodape fino. Margens de 48 pt (0,67 in).
// ---------------------------------------------------------------------------

var M = 48, W = 516, XR = M + W;            // margem, largura util, borda direita
var BANDA = 104, BANDA_CONT = 60;           // faixa moss da pag 1 e das continuacoes
var CORPO_FIM = 746;                        // ultimo y util do corpo (filete do rodape em 754)
var COL = { qtd: 392, unit: 452, desc: 508, total: XR };
var COL_SEM = { qtd: 420, unit: 496, desc: null, total: XR };
var FOTO = 80, TXT_X = M + FOTO + 14, LINHA_MIN = FOTO + 26, EXTRA_H = 34;
var CX = [M, M + 180, M + 360], CW = 156;   // tres colunas de 156 com vao de 24
var SX = 348, SW = XR - SX, SP = 12;        // caixa Sand do resumo

function colunaBill(pg, x, entradas, primeiraNegrito) {
  return colunaCampos(pg, entradas, { x: x, w: CW, yIni: 180, lineH: 12, size: 9, sizeMin: 7.5, cor: COR.moss, corNegrito: COR.charcoal, primeiraNegrito: primeiraNegrito }).cortes;
}
function colunaDet(pg, x, linhas) {
  return colunaDetalhes(pg, linhas, { x: x, w: CW, wRot: 64, yIni: 180, lineH: 12, size: 9, sizeMin: 7.5, corRot: COR.sec, cor: COR.moss }).cortes;
}
// campos que sairiam cortados com "…" (o Montar Rascunho avisa no resumo antes de numerar)
function medirCortes(doc) {
  return colunaBill(null, CX[0], doc.bill_to, true).concat(colunaBill(null, CX[1], doc.deliver_to, false)).concat(colunaDet(null, CX[2], doc.detalhes));
}
// (da direcao B) "H 36 in · W 28 in · Opening 28 in · Base 11 in · 252 lb" -> celulas da grade;
// null se o texto nao segue o padrao do medidasTexto (ai a linha sai em texto corrido, como no A)
function gradeMedidas(txt) {
  var partes = String(txt || '').split(' · '), cels = [];
  for (var i = 0; i < partes.length; i++) {
    var p = partes[i], m;
    if ((m = /^H (.+)$/.exec(p))) cels.push(['Height', m[1]]);
    else if ((m = /^W (.+)$/.exec(p))) cels.push(['Width', m[1]]);
    else if ((m = /^Opening (.+)$/.exec(p))) cels.push(['Opening', m[1]]);
    else if ((m = /^Base (.+)$/.exec(p))) cels.push(['Base', m[1]]);
    else if ((m = /^([\d.]+ lb)$/.exec(p))) cels.push(['Weight', m[1]]);
    else return null;
  }
  return cels.length ? cels : null;
}

function buildInvoicePdf(doc, imgs) {
  var avisos = [];
  var logoOk = true;
  try { jpegInfo(Buffer.from(String(imgs && imgs.logo && imgs.logo.b64 || ''), 'base64')); } catch (err) { logoOk = false; }
  if (!logoOk) throw new Error('logo invalido: JPEG do logo ausente ou invalido');
  var R = registrarImagens(imgs, avisos), fotos = R.fotos;
  var selo = (doc.selo || []).filter(Boolean).slice(0, 2);
  selo.forEach(function (s) { if (textWidth(s, RG, 6.5) > FOTO + 4) throw new Error('selo nao cabe: ' + s); });
  var col = doc.com_desconto === false ? COL_SEM : COL;
  var TXT_W = col.qtd - 24 - TXT_X;
  var CEL = Math.min(46, Math.floor(TXT_W / 5));     // largura de cada celula da grade de medidas
  if (!doc.itens || !doc.itens.length) throw new Error('invoice sem pecas');

  // ---- passada 1: alturas
  function layoutItem(it) {
    var t = quebrar(it.titulo, BD, 11, TXT_W, 2), d = quebrar(it.detalhe, RG, 8, TXT_W, 2);
    var grade = it.medidas_pendente ? null : gradeMedidas(it.medidas);
    var m = grade ? { linhas: [] } : quebrar(it.medidas, RG, 8, TXT_W, 2);
    var nf = it.nota_foto ? quebrar(it.nota_foto, RG, 7.5, TXT_W, 2) : { linhas: [] };
    var pos = { tit: 22 };
    pos.det = pos.tit + 3 + Math.max(1, t.linhas.length) * 13;
    var yy = pos.det + (Math.max(1, d.linhas.length) - 1) * 11 + 12;
    if (it.sku) { pos.sku = yy; yy += 12; }
    var fim;
    if (grade) { pos.gradeRot = yy + 2; pos.gradeVal = yy + 13; fim = pos.gradeVal; }
    else { pos.med = yy; fim = pos.med + (Math.max(1, m.linhas.length) - 1) * 11; }
    if (nf.linhas.length) { pos.nota = fim + 12; fim = pos.nota + (nf.linhas.length - 1) * 10; }
    return { t: t, d: d, m: m, nf: nf, grade: grade, pos: pos, h: Math.max(LINHA_MIN, fim + 12) };
  }
  var linhas = (doc.itens || []).map(function (it) { var lay = layoutItem(it); return { tipo: 'item', it: it, lay: lay, h: lay.h }; })
    .concat((doc.extras || []).map(function (ex) { return { tipo: 'extra', ex: ex, h: EXTRA_H }; }));
  var hF = fechamento(null, 0);
  if (hF > 600) throw new Error('dados de pagamento ou condições não cabem numa página');
  var P = paginar(linhas, { yIni1: 262, yIniN: BANDA_CONT + 46, corpoFim: CORPO_FIM, gapFech: 14, yFechN: BANDA_CONT + 30 }, hF);
  var plano = P.plano, N = P.N;

  // ---- blocos
  function faixaTeste(pg, yTopo) {
