    drawText(pg, doc.faixa_texto || 'TEST · NOT A VALID INVOICE · NO TAX OR PAYMENT VALUE', { x: PAGE_W / 2, baseline: yTopo + 8.6, font: BD, size: 6.5, color: COR.branco, align: 'center', maxWidth: 520, shrink: true, tc: 0.5 });
  }
  function cabecalho1(pg) {
    drawRect(pg, { x: 0, y: 0, w: PAGE_W, h: BANDA, color: COR.moss });
    drawLogo(pg, { x: M, y: 24, h: 36, color: COR.sand });
    drawText(pg, doc.tagline, { x: M, baseline: 82, font: RG, size: 6.5, color: COR.ochreClaro, maxWidth: 300, shrink: true, tc: 0.5 });
    rotulo(pg, 'Invoice', XR, 40, { font: RG, size: 10, color: COR.ochreClaro, tc: 3, align: 'right' });
    drawText(pg, doc.numero, { x: XR, baseline: 62, font: BD, size: 17, color: COR.sand, align: 'right', maxWidth: 260, shrink: true });
    drawText(pg, 'Issued ' + doc.emitida + '   ·   Valid until ' + doc.validade, { x: XR, baseline: 82, font: RG, size: 8, color: COR.sand, align: 'right' });
    if (doc.teste) faixaTeste(pg, BANDA - 12);
    var prep = drawText(pg, 'Prepared by ' + doc.preparado_por + ' · Horizon Group', { x: XR, baseline: 130, font: RG, size: 8, color: COR.sec, align: 'right', maxWidth: 200, shrink: true });
    linhaEmpresa(pg, doc.empresa_linha, { x: M, baseline: 130, size: 8, color: COR.moss, corResto: COR.sec, maxWidth: W - prep.largura - 16 });
    [['Bill to', CX[0]], ['Deliver to', CX[1]], ['Invoice details', CX[2]]].forEach(function (c) {
      rotulo(pg, c[0], c[1], 158, { size: 7, tc: 1.1 });
