    drawText(pg, o.total, { x: col.total, baseline: yb, font: BD, size: 9.5, color: COR.charcoal, align: 'right', maxWidth: 56, shrink: true });
  }
  function desenharLinha(pg, r, yr) {
    if (r.tipo === 'item') {
