      : (en ? '(' + cond + ' County, tax ' + fmtUSD(t.imposto_total_cents) + ')' : '(' + cond + ', imposto ' + fmtUSD(t.imposto_total_cents) + ')');
    var caption = (base.teste ? (en ? 'TEST · ' : 'TESTE · ') : '') + 'Invoice ' + numero + ' · ' + cliente + ' · ' + fmtUSD(t.total_cents) + ' ' + paren +
