function indexarCatalogo(catalogo) {
  var porProduto = {}, lista = [];
  catalogo.forEach(function (row) {
    var k = normProduto(row.produto);
    if (!porProduto[k]) { porProduto[k] = { produto: row.produto, colecao: row.colecao, chaves: [k], rows: [] }; lista.push(porProduto[k]); }
    var p = porProduto[k];
    p.rows.push(row);
    (row.apelidos || []).forEach(function (a) { var ka = normProduto(a); if (p.chaves.indexOf(ka) < 0) p.chaves.push(ka); });
  });
  return lista;
}
function acharProduto(lista, texto) {
  var k = normProduto(texto);
  if (!k) return { erro: 'nao', parecidos: [] };
  var exatos = lista.filter(function (p) { return p.chaves.indexOf(k) >= 0; });
  if (exatos.length === 1) return { produto: exatos[0] };
  if (exatos.length > 1) return { erro: 'ambiguo', opcoes: exatos.map(function (p) { return p.produto; }) };
  var comeca = lista.filter(function (p) { return p.chaves.some(function (c) { return c.indexOf(k + ' ') === 0; }); });
  if (comeca.length === 1) return { produto: comeca[0] };
  if (comeca.length > 1) return { erro: 'ambiguo', opcoes: comeca.map(function (p) { return p.produto; }) };
  var parecidos = lista.map(function (p) { return { p: p.produto, d: Math.min.apply(null, p.chaves.map(function (c) { return levenshtein(k, c); })) }; })
    .filter(function (x) { return x.d <= 2; }).sort(function (a, b) { return a.d - b.d || (a.p < b.p ? -1 : 1); }).slice(0, 3)
    .map(function (x) { return x.p; });
  return { erro: 'nao', parecidos: parecidos };
}
function vigente(row, hoje) {
  var ini = isoData(row.vigencia_inicio), fim = row.vigencia_fim ? isoData(row.vigencia_fim) : null;
  return ini <= hoje && (!fim || fim >= hoje);
}
function canonCondado(condados, nome) {
  var n = normCondado(nome);
  if (!n) return '';
  for (var i = 0; i < condados.length; i++) {
    var r = condados[i];
    if (normCondado(r.condado) === n || (r.apelidos || []).some(function (a) { return normCondado(a) === n; })) return r.condado;
  }
