// registro de JPEGs (XObject unico por sha256) e serializacao: iguais nas tres direcoes
function registrarImagens(imgs, avisos) {
  var reg = [], porSha = {};
  function registrar(b64) {
    var buf = Buffer.from(String(b64 || ''), 'base64');
    var info = jpegInfo(buf);
    if (!info.width || !info.height) throw new Error('JPEG sem dimensao');
    var sha = sha256Hex(buf);
    if (porSha[sha] !== undefined) return reg[porSha[sha]];
    var img = { nome: 'Im' + reg.length, buf: buf, info: info, sha: sha };
    porSha[sha] = reg.length; reg.push(img);
    return img;
  }
  var fotos = ((imgs && imgs.fotos) || []).map(function (f, i) {
    if (!f || !f.b64) return null;
    try { return registrar(f.b64); } catch (err) { avisos.push('foto ' + (i + 1) + ' invalida (' + err.message + '): a linha sai com "Photo on request"'); return null; }
  });
  return { reg: reg, fotos: fotos };
}
function serializarPdf(paginas, reg) {
  var objects = [];
  function addObj(body) { objects.push(body); return objects.length; }
  addObj('<< /Type /Catalog /Pages 2 0 R >>');
  var pagesIdx = addObj('') - 1;
  var fontNum = {};
  [RG, BD].forEach(function (bf) { fontNum[bf] = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /' + bf + ' /Encoding /WinAnsiEncoding >>'); });
  var fontRes = '/' + FONT_RES[RG] + ' ' + fontNum[RG] + ' 0 R /' + FONT_RES[BD] + ' ' + fontNum[BD] + ' 0 R';
  var imgNum = {};
  reg.forEach(function (img) {
    var usada = paginas.some(function (pg) { return pg.imgs.indexOf(img) >= 0; });
    if (!usada) return;
    var cs = img.info.components === 1 ? '/DeviceGray' : img.info.components === 4 ? '/DeviceCMYK' : '/DeviceRGB';
    var extra = img.info.components === 4 ? ' /Decode [1 0 1 0 1 0 1 0]' : '';
    imgNum[img.nome] = addObj({
      dict: '<< /Type /XObject /Subtype /Image /Width ' + img.info.width + ' /Height ' + img.info.height + ' /ColorSpace ' + cs +
        ' /BitsPerComponent 8' + extra + ' /Filter /DCTDecode /Length ' + img.buf.length + ' >>', stream: img.buf
    });
  });
  var pageNums = [];
  paginas.forEach(function (pg) {
    var buf = Buffer.from(pg.ops.join(''), 'latin1');
    var cNum = addObj({ dict: '<< /Length ' + buf.length + ' >>', stream: buf });
    var xo = pg.imgs.map(function (img) { return '/' + img.nome + ' ' + imgNum[img.nome] + ' 0 R'; }).join(' ');
    pageNums.push(addObj('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + PAGE_W + ' ' + PAGE_H + ']' +
      ' /Resources << /Font << ' + fontRes + ' >>' + (xo ? ' /XObject << ' + xo + ' >>' : '') +
      ' >> /Contents ' + cNum + ' 0 R >>'));
  });
  objects[pagesIdx] = '<< /Type /Pages /Count ' + pageNums.length + ' /Kids [' + pageNums.map(function (n) { return n + ' 0 R'; }).join(' ') + '] >>';
  var chunks = [], offset = 0;
  function push(x) { var b = Buffer.isBuffer(x) ? x : Buffer.from(x, 'latin1'); chunks.push(b); offset += b.length; }
  push('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  var xref = [0];
  objects.forEach(function (body, i) {
    xref.push(offset);
    push((i + 1) + ' 0 obj\n');
    if (typeof body === 'string') push(body + '\nendobj\n');
    else { push(body.dict + '\nstream\n'); push(body.stream); push('\nendstream\nendobj\n'); }
  });
  var xrefOff = offset, count = objects.length + 1;
  push('xref\n0 ' + count + '\n');
  push('0000000000 65535 f \n');
  for (var j = 1; j < count; j++) push(('0000000000' + xref[j]).slice(-10) + ' 00000 n \n');
  push('trailer\n<< /Size ' + count + ' /Root 1 0 R >>\nstartxref\n' + xrefOff + '\n%%EOF\n');
  return Buffer.concat(chunks);
}

// rotulo em caixa alta com tracking (usado nos tres designs)
function rotulo(pg, s, x, baseline, o) {
