}

// Coluna de campos (BILL TO / DELIVER TO) parametrizada; entradas: [{campo, texto, linhas?}], vazias omitidas,
// ate 5 linhas; devolve os campos cortados com "…" (o Montar Rascunho avisa no resumo antes de numerar).
// o: {x, w, yIni (baseline da 1a linha), lineH, size, sizeMin, cor, corNegrito, primeiraNegrito, maxLinhas}
function colunaCampos(pg, entradas, o) {
  var usadas = 0, cortes = [], maxL5 = o.maxLinhas || 5, size0 = o.size || 9, sizeMin = o.sizeMin || 7.5;
  (entradas || []).filter(function (en) { return en && en.texto; }).forEach(function (en, i) {
    var font = (o.primeiraNegrito && i === 0) ? BD : RG, cor = (o.primeiraNegrito && i === 0 && o.corNegrito) ? o.corNegrito : o.cor;
    if (usadas >= maxL5) { cortes.push(en.campo); return; }
    var maxL = Math.min(en.linhas || 1, maxL5 - usadas);
    if (maxL > 1) {
      var size = size0, q = quebrar(en.texto, font, size0, o.w, 0, true), cortou = false;
      if (q.linhas.length > maxL) { size = sizeMin; q = quebrar(en.texto, font, sizeMin, o.w, 0, true); }
      if (q.linhas.length > maxL) { q = quebrar(en.texto, font, sizeMin, o.w, maxL, false); cortou = true; }
      q.linhas.forEach(function (l) { if (pg) pg.add(textOpTc(l, font, size, cor, o.x, PAGE_H - (o.yIni + usadas * o.lineH), 0)); usadas++; });
      if (cortou) cortes.push(en.campo);
    } else {
      var r = drawText(pg, en.texto, { x: o.x, baseline: o.yIni + usadas * o.lineH, font: font, size: size0, color: cor, maxWidth: o.w, shrink: true, minSize: sizeMin });
      if (r.cortado) cortes.push(en.campo);
      usadas++;
    }
  });
  return { cortes: cortes, linhas: usadas };
}
// pares rotulo/valor (INVOICE DETAILS); o: {x, w, wRot, yIni, lineH, size, sizeMin, corRot, cor}
function colunaDetalhes(pg, linhas, o) {
  var cortes = [], size0 = o.size || 9, sizeMin = o.sizeMin || 7.5;
  (linhas || []).slice(0, o.maxLinhas || 5).forEach(function (l, i) {
    drawText(pg, l[0], { x: o.x, baseline: o.yIni + i * o.lineH, font: RG, size: size0, color: o.corRot, maxWidth: o.wRot - 6, shrink: true, minSize: sizeMin });
    var r = drawText(pg, l[1], { x: o.x + o.wRot, baseline: o.yIni + i * o.lineH, font: o.valorNegrito ? BD : RG, size: size0, color: o.cor, maxWidth: o.w - o.wRot, shrink: true, minSize: sizeMin });
    if (r.cortado) cortes.push(l[0]);
  });
  return { cortes: cortes, linhas: Math.min((linhas || []).length, o.maxLinhas || 5) };
}
// empresa_linha: a parte antes do primeiro "·" em negrito; devolve a largura usada
function linhaEmpresa(pg, texto, o) {
  var emp = String(texto || ''), k = emp.indexOf('·');
  var negrito = k > 0 ? emp.slice(0, k).trim() : emp, resto = k > 0 ? ' ' + emp.slice(k) : '';
  var size = o.size, wTot = textWidth(negrito, BD, size) + textWidth(resto, RG, size);
  if (wTot > o.maxWidth) size = Math.max(o.minSize || 6.5, size * o.maxWidth / wTot);
  var wN = drawText(pg, negrito, { x: o.x, baseline: o.baseline, font: BD, size: size, color: o.color }).largura;
  drawText(pg, resto, { x: o.x + wN, baseline: o.baseline, font: RG, size: size, color: o.corResto || o.color, maxWidth: o.maxWidth - wN });
  return Math.min(wTot, o.maxWidth);
}
// paginacao comum: linhas (com .h) empilhadas a partir de yIni1 (pag 1) / yIniN (continuacao) ate corpoFim;
// o fechamento (hF) nunca se divide. Devolve {plano:[{pag,y,r}], comTabela:[], pagFech, yC, N}
function paginar(linhas, o, hF) {
  var plano = [], pag = 0, y = o.yIni1, comTabela = [true];
  linhas.forEach(function (r) {
    if (y + r.h > o.corpoFim) { pag++; y = o.yIniN; comTabela[pag] = true; }
    plano.push({ pag: pag, y: y, r: r }); y += r.h;
  });
  var yC;
  if (y + o.gapFech + hF > o.corpoFim) { pag++; yC = o.yFechN; } else yC = y + o.gapFech;
  return { plano: plano, comTabela: comTabela, pagFech: pag, yC: yC, N: pag + 1 };
}

