}
// (da direcao B) "H 36 in · W 28 in · Opening 28 in · Base 11 in · 252 lb" -> celulas da grade;
// null se o texto nao segue o padrao do medidasTexto (ai a linha sai em texto corrido, como no A)
function gradeMedidas(txt) {
  var partes = String(txt || '').split(' · '), cels = [];
  for (var i = 0; i < partes.length; i++) {
    var p = partes[i], m;
    if ((m = /^H (.+)$/.exec(p))) cels.push(['Height', m[1]]);
    else if ((m = /^W (.+)$/.exec(p))) cels.push(['Width', m[1]]);
    else if ((m = /^Opening (.+)$/.exec(p))) cels.push(['Opening', m[1]]);
    else if ((m = /^Base (.+)$/.exec(p))) cels.push(['Base', m[1]]);
    else if ((m = /^([\d.]+ lb)$/.exec(p))) cels.push(['Weight', m[1]]);
    else return null;
  }
  return cels.length ? cels : null;
}

function buildInvoicePdf(doc, imgs) {
  var avisos = [];
  var logoOk = true;
  try { jpegInfo(Buffer.from(String(imgs && imgs.logo && imgs.logo.b64 || ''), 'base64')); } catch (err) { logoOk = false; }
  if (!logoOk) throw new Error('logo invalido: JPEG do logo ausente ou invalido');
  var R = registrarImagens(imgs, avisos), fotos = R.fotos;
  var selo = (doc.selo || []).filter(Boolean).slice(0, 2);
  selo.forEach(function (s) { if (textWidth(s, RG, 6.5) > FOTO + 4) throw new Error('selo nao cabe: ' + s); });
  var col = doc.com_desconto === false ? COL_SEM : COL;
  var TXT_W = col.qtd - 24 - TXT_X;
  var CEL = Math.min(46, Math.floor(TXT_W / 5));     // largura de cada celula da grade de medidas
  if (!doc.itens || !doc.itens.length) throw new Error('invoice sem pecas');

  // ---- passada 1: alturas
  function layoutItem(it) {
    var t = quebrar(it.titulo, BD, 11, TXT_W, 2), d = quebrar(it.detalhe, RG, 8, TXT_W, 2);
    var grade = it.medidas_pendente ? null : gradeMedidas(it.medidas);
    var m = grade ? { linhas: [] } : quebrar(it.medidas, RG, 8, TXT_W, 2);
    var nf = it.nota_foto ? quebrar(it.nota_foto, RG, 7.5, TXT_W, 2) : { linhas: [] };
    var pos = { tit: 22 };
    pos.det = pos.tit + 3 + Math.max(1, t.linhas.length) * 13;
    var yy = pos.det + (Math.max(1, d.linhas.length) - 1) * 11 + 12;
    if (it.sku) { pos.sku = yy; yy += 12; }
    var fim;
    if (grade) { pos.gradeRot = yy + 2; pos.gradeVal = yy + 13; fim = pos.gradeVal; }
    else { pos.med = yy; fim = pos.med + (Math.max(1, m.linhas.length) - 1) * 11; }
    if (nf.linhas.length) { pos.nota = fim + 12; fim = pos.nota + (nf.linhas.length - 1) * 10; }
    return { t: t, d: d, m: m, nf: nf, grade: grade, pos: pos, h: Math.max(LINHA_MIN, fim + 12) };
  }
  var linhas = (doc.itens || []).map(function (it) { var lay = layoutItem(it); return { tipo: 'item', it: it, lay: lay, h: lay.h }; })
    .concat((doc.extras || []).map(function (ex) { return { tipo: 'extra', ex: ex, h: EXTRA_H }; }));
  var hF = fechamento(null, 0);
  if (hF > 600) throw new Error('dados de pagamento ou condições não cabem numa página');
  var P = paginar(linhas, { yIni1: 262, yIniN: BANDA_CONT + 46, corpoFim: CORPO_FIM, gapFech: 14, yFechN: BANDA_CONT + 30 }, hF);
  var plano = P.plano, N = P.N;

  // ---- blocos
  function faixaTeste(pg, yTopo) {
    drawRect(pg, { x: 0, y: yTopo, w: PAGE_W, h: 12, color: COR.ochre });
    drawText(pg, doc.faixa_texto || 'TEST · NOT A VALID INVOICE · NO TAX OR PAYMENT VALUE', { x: PAGE_W / 2, baseline: yTopo + 8.6, font: BD, size: 6.5, color: COR.branco, align: 'center', maxWidth: 520, shrink: true, tc: 0.5 });
  }
  function cabecalho1(pg) {
    drawRect(pg, { x: 0, y: 0, w: PAGE_W, h: BANDA, color: COR.moss });
    drawLogo(pg, { x: M, y: 24, h: 36, color: COR.sand });
    drawText(pg, doc.tagline, { x: M, baseline: 82, font: RG, size: 6.5, color: COR.ochreClaro, maxWidth: 300, shrink: true, tc: 0.5 });
    rotulo(pg, 'Invoice', XR, 40, { font: RG, size: 10, color: COR.ochreClaro, tc: 3, align: 'right' });
    drawText(pg, doc.numero, { x: XR, baseline: 62, font: BD, size: 17, color: COR.sand, align: 'right', maxWidth: 260, shrink: true });
    drawText(pg, 'Issued ' + doc.emitida + '   ·   Valid until ' + doc.validade, { x: XR, baseline: 82, font: RG, size: 8, color: COR.sand, align: 'right' });
    if (doc.teste) faixaTeste(pg, BANDA - 12);
    var prep = drawText(pg, 'Prepared by ' + doc.preparado_por + ' · Horizon Group', { x: XR, baseline: 130, font: RG, size: 8, color: COR.sec, align: 'right', maxWidth: 200, shrink: true });
    linhaEmpresa(pg, doc.empresa_linha, { x: M, baseline: 130, size: 8, color: COR.moss, corResto: COR.sec, maxWidth: W - prep.largura - 16 });
    [['Bill to', CX[0]], ['Deliver to', CX[1]], ['Invoice details', CX[2]]].forEach(function (c) {
      rotulo(pg, c[0], c[1], 158, { size: 7, tc: 1.1 });
      drawHLine(pg, c[1], 164, CW, COR.ochre, 0.5);
    });
    colunaBill(pg, CX[0], doc.bill_to, true);
    colunaBill(pg, CX[1], doc.deliver_to, false);
    colunaDet(pg, CX[2], doc.detalhes);
  }
  function cabecalhoCont(pg) {
    drawRect(pg, { x: 0, y: 0, w: PAGE_W, h: BANDA_CONT, color: COR.moss });
    drawLogo(pg, { x: M, y: 17, h: 22, color: COR.sand });
    rotulo(pg, 'Invoice', XR, 26, { font: RG, size: 7.5, color: COR.ochreClaro, tc: 2.5, align: 'right' });
    drawText(pg, doc.numero + '  ·  continued', { x: XR, baseline: 40, font: BD, size: 9.5, color: COR.sand, align: 'right' });
    if (doc.teste) faixaTeste(pg, BANDA_CONT - 12);
  }
  function cabecalhoTabela(pg, yt) {
    var b = yt + 9;
    rotulo(pg, 'Item', M, b, { size: 7, color: COR.sec, tc: 1.1 });
    rotulo(pg, 'Qty', col.qtd, b, { size: 7, color: COR.sec, tc: 1.1, align: 'right' });
    rotulo(pg, 'Unit price', col.unit, b, { size: 7, color: COR.sec, tc: 1.1, align: 'right' });
    if (col.desc) rotulo(pg, 'Discount', col.desc, b, { size: 7, color: COR.sec, tc: 1.1, align: 'right' });
    rotulo(pg, 'Amount', col.total, b, { size: 7, color: COR.sec, tc: 1.1, align: 'right' });
    drawHLine(pg, M, yt + 16, W, COR.moss, 0.8);
  }
  function numeros(pg, o, yb) {
    drawText(pg, o.qtd, { x: col.qtd, baseline: yb, font: RG, size: 9.5, color: COR.moss, align: 'right' });
    drawText(pg, o.unit, { x: col.unit, baseline: yb, font: RG, size: 9.5, color: COR.moss, align: 'right', maxWidth: 62, shrink: true });
    if (col.desc) {
      var temDesc = o.desconto && o.desconto !== '—';
      drawText(pg, o.desconto || '—', { x: col.desc, baseline: yb, font: RG, size: 9.5, color: temDesc ? COR.ochre : COR.sec, align: 'right', maxWidth: 56, shrink: true });
      if (o.desconto_sub) drawText(pg, o.desconto_sub, { x: col.desc, baseline: yb + 11, font: RG, size: 7, color: COR.sec, align: 'right' });
    }
    drawText(pg, o.total, { x: col.total, baseline: yb, font: BD, size: 9.5, color: COR.charcoal, align: 'right', maxWidth: 56, shrink: true });
  }
  function desenharLinha(pg, r, yr) {
    if (r.tipo === 'item') {
      var it = r.it, L = r.lay, fx = M, fy = yr + 10;
      var img = (it.foto !== null && it.foto !== undefined) ? fotos[it.foto] : null;
      if (img) {
        drawRect(pg, { x: fx, y: fy, w: FOTO, h: FOTO, color: COR.branco });
        drawImage(pg, img, { x: fx + 1, y: fy + 1, w: FOTO - 2, h: FOTO - 2 });
        drawBox(pg, { x: fx, y: fy, w: FOTO, h: FOTO, stroke: COR.filete, width: 0.5 });
        selo.forEach(function (s, i) { drawText(pg, s, { x: fx + FOTO / 2, baseline: fy + FOTO + 9 + i * 8, font: RG, size: 6.5, color: COR.sec, align: 'center' }); });
      } else {
        drawRect(pg, { x: fx, y: fy, w: FOTO, h: FOTO, color: COR.sand });
        drawText(pg, 'Photo on request', { x: fx + FOTO / 2, baseline: fy + FOTO / 2 + 3, font: RG, size: 7, color: COR.sec, align: 'center' });
      }
      L.t.linhas.forEach(function (l, i) { drawText(pg, l, { x: TXT_X, baseline: yr + L.pos.tit + i * 13, font: BD, size: 11, color: COR.charcoal }); });
      L.d.linhas.forEach(function (l, i) { drawText(pg, l, { x: TXT_X, baseline: yr + L.pos.det + i * 11, font: RG, size: 8, color: COR.moss }); });
      if (it.sku) drawText(pg, it.sku, { x: TXT_X, baseline: yr + L.pos.sku, font: RG, size: 7.5, color: COR.sec, maxWidth: TXT_W, tc: 0.3 });
      if (L.grade) {
        L.grade.forEach(function (c, i) {
          var x = TXT_X + i * CEL;
          rotulo(pg, c[0], x, yr + L.pos.gradeRot, { size: 5.5, color: COR.ochre, tc: 0.8 });
          drawText(pg, c[1], { x: x, baseline: yr + L.pos.gradeVal, font: RG, size: 8.5, color: COR.moss, maxWidth: CEL - 4, shrink: true, minSize: 6.5 });
        });
      } else {
        L.m.linhas.forEach(function (l, i) { drawText(pg, l, { x: TXT_X, baseline: yr + L.pos.med + i * 11, font: RG, size: 8, color: it.medidas_pendente ? COR.sec : COR.moss }); });
      }
      L.nf.linhas.forEach(function (l, i) { drawText(pg, l, { x: TXT_X, baseline: yr + L.pos.nota + i * 10, font: RG, size: 7.5, color: COR.ochre }); });
      numeros(pg, it, yr + 22);
    } else {
      var ex = r.ex;
      drawText(pg, ex.titulo, { x: M, baseline: yr + 16, font: BD, size: 9.5, color: COR.charcoal, maxWidth: 300 });
      drawText(pg, ex.sub, { x: M, baseline: yr + 27, font: RG, size: 7.5, color: COR.sec, maxWidth: 300 });
      numeros(pg, ex, yr + 16);
    }
    drawHLine(pg, M, yr + r.h - 0.5, W, COR.filete, 0.5);
  }
  // bloco de fechamento (nunca se divide); com pg = null so mede e devolve a altura
  function fechamento(pg, y0) {
    // resumo (direita, caixa Sand): mede primeiro para pintar a caixa por tras
    var yb = y0 + SP + 20, fimDir;
    var ops = [];
    (doc.resumo || []).forEach(function (row) {
      var rot = row[0], val = row[1], subs = row[2] ? [].concat(row[2]) : [], estilo = row[3];
      if (estilo === 'total') {
        ops.push(['linha', yb - 8]);
        yb += 8;
        ops.push(['txt', rot, SX + SP, yb, BD, 13, COR.charcoal]); ops.push(['txtR', val, XR - SP, yb, BD, 13, COR.charcoal]);
        fimDir = yb + 4; yb += 20;
      } else if (estilo === 'saldo') {
        ops.push(['txt', rot, SX + SP, yb, BD, 10, COR.moss]); ops.push(['txtR', val, XR - SP, yb, BD, 10, COR.ochre]);
        fimDir = yb + 4; yb += 16;
      } else {
        var wv = textWidth(val, RG, 9);
        ops.push(['txtR', val, XR - SP, yb, RG, 9, COR.moss]);
        ops.push(['txtMax', rot, SX + SP, yb, RG, 9, COR.moss, SW - 2 * SP - wv - 8]);
        var ys = yb;
        subs.forEach(function (s) {
          var q = quebrar(s, RG, 6.8, SW - 2 * SP, 3);
          q.linhas.forEach(function (l, i) { ops.push(['txt', l, SX + SP, ys + 9 + i * 8.5, RG, 6.8, COR.sec]); });
          ys += q.linhas.length * 8.5;
        });
        fimDir = ys + 4; yb = ys + 16;
      }
    });
    var hCaixa = fimDir + SP - 4 - y0;
    if (pg) {
      drawRect(pg, { x: SX, y: y0, w: SW, h: hCaixa, color: COR.sand });
      rotulo(pg, 'Summary', SX + SP, y0 + SP, { size: 7, tc: 1.1 });
      ops.forEach(function (o) {
        if (o[0] === 'linha') drawHLine(pg, SX + SP, o[1], SW - 2 * SP, COR.moss, 0.8);
        else if (o[0] === 'txt') drawText(pg, o[1], { x: o[2], baseline: o[3], font: o[4], size: o[5], color: o[6] });
        else if (o[0] === 'txtR') drawText(pg, o[1], { x: o[2], baseline: o[3], font: o[4], size: o[5], color: o[6], align: 'right' });
        else drawText(pg, o[1], { x: o[2], baseline: o[3], font: o[4], size: o[5], color: o[6], maxWidth: o[7], shrink: true, minSize: 7 });
      });
    }
    // esquerda: HOW TO PAY + TERMS
    var LW = SX - M - 24;
    rotulo(pg, 'How to pay', M, y0 + SP, { size: 7, tc: 1.1 });
    var yl = y0 + SP + 16;
    var pagamentos = doc.pagamento || [];
    if (pagamentos.length) {
      pagamentos.forEach(function (p) {
        var cor = p[2] === 'placeholder' ? COR.sec : COR.moss, val = String(p[1] == null ? '' : p[1]);
        drawText(pg, p[0], { x: M, baseline: yl, font: BD, size: 8.5, color: COR.charcoal, maxWidth: 66 });
        if (/^\S+$/.test(val) && textWidth(val, RG, 8.5) > LW - 74 && textWidth(val, RG, 6.5) <= LW) {
          // link (um token so) que nao cabe ao lado do rotulo: linha propria, inteiro, encolhendo ate 6,5 pt
          // (um link nunca se quebra no meio nem sai cortado com "…")
          drawText(pg, val, { x: M, baseline: yl + 11, font: RG, size: 8.5, color: cor, maxWidth: LW, shrink: true, minSize: 6.5 });
          yl += 22 + 2;
        } else {
          var q = drawWrap(pg, val, { x: M + 74, baseline: yl, font: RG, size: 8.5, color: cor, maxWidth: LW - 74, lineHeight: 11, nuncaCortar: true });
          yl += Math.max(1, q.linhas) * 11 + 2;
        }
      });
    } else {
      var q0 = drawWrap(pg, 'Payment instructions will be sent separately.', { x: M, baseline: yl, font: RG, size: 8.5, color: COR.moss, maxWidth: LW, lineHeight: 11, nuncaCortar: true });
      yl += q0.linhas * 11 + 3;
    }
    if (doc.referencia) {
      var q1 = drawWrap(pg, doc.referencia, { x: M, baseline: yl + 1, font: RG, size: 7.5, color: COR.sec, maxWidth: LW, lineHeight: 10, nuncaCortar: true });
      yl += q1.linhas * 10 + 4;
    }
    rotulo(pg, 'Terms', M, yl + 10, { size: 7, tc: 1.1 });
    yl += 24;
    (doc.condicoes || []).forEach(function (c) {
      var texto = typeof c === 'string' ? c : c.texto, cor = (c && c.reservado) ? COR.sec : COR.moss;
      drawText(pg, '•', { x: M, baseline: yl, font: RG, size: 7.5, color: cor });
      var q = drawWrap(pg, texto, { x: M + 9, baseline: yl, font: RG, size: 7.5, color: cor, maxWidth: LW - 9, lineHeight: 10, nuncaCortar: true });
      yl += Math.max(1, q.linhas) * 10 + 1.5;
    });
    var fimEsq = yl - 9;
    return Math.max(fimEsq, y0 + hCaixa) - y0 + 6;
  }
  function rodape(pg, i) {
    drawHLine(pg, M, 754, W, COR.filete, 0.5);
    var dir = doc.numero + '  ·  Page ' + i + ' of ' + N + (doc.teste ? '  ·  ' + (doc.marca_dagua || 'TEST') : '');
    var w = drawText(pg, dir, { x: XR, baseline: 765, font: RG, size: 7, color: COR.sec, align: 'right' }).largura;
    drawText(pg, doc.rodape, { x: M, baseline: 765, font: RG, size: 7, color: COR.sec, maxWidth: W - w - 14, shrink: true, minSize: 5.5 });
  }

  // ---- passada 2: desenha
  var paginas = [];
  for (var p = 0; p < N; p++) {
    var pg = new Pagina();
    if (doc.marca_dagua) marcaDagua(pg, doc.marca_dagua);
    if (p === 0) cabecalho1(pg); else cabecalhoCont(pg);
    if (P.comTabela[p]) cabecalhoTabela(pg, p === 0 ? 236 : BANDA_CONT + 18);
    plano.forEach(function (x) { if (x.pag === p) desenharLinha(pg, x.r, x.y); });
    if (p === P.pagFech) fechamento(pg, P.yC);
    rodape(pg, p + 1);
    paginas.push(pg);
  }
  return {
    pdf_b64: serializarPdf(paginas, R.reg).toString('base64'), paginas: N, avisos: avisos,
    layout: {
      linhas: plano.map(function (x) { return { pag: x.pag + 1, y: x.y, h: x.r.h, tipo: x.r.tipo, titulo: x.r.tipo === 'item' ? x.r.it.titulo : x.r.ex.titulo }; }),
      fechamento: { pag: P.pagFech + 1, y: P.yC, h: hF }
    }
  };
}

// ---------------------------------------------------------------------------
// montarDoc (funcao pura): calculo guardado -> doc do gerador, com limparTexto em todo texto
// entrada: { webhook_teste, teste, marca_dagua, numero, emitida_em, validade, calculo, certificado_revenda,
//            solicitante_nome, config, logo_b64, fotos: {sku: {b64, sha256, url}} }
// ---------------------------------------------------------------------------

// serie de teste: HP-I-T-AAAA-NNNN (teste real) e HP-I-TEST-0000 (webhook de teste) sempre levam a faixa TEST
var RE_SERIE_TESTE = /^HP-I-T(EST)?-/;
function serieTeste(numero) { return RE_SERIE_TESTE.test(String(numero == null ? '' : numero).trim()); }

function montarDoc(entrada) {
  var c = entrada.calculo, cfg = entrada.config || {}, avisos = [];
  function L(s) { return limparTexto(s, avisos); }
  var numero = L(entrada.numero), validade = fmtData(entrada.validade);
  var t = c.totais, cond = c.condado, teste = entrada.teste === true || serieTeste(numero);
  var marca = entrada.marca_dagua ? L(entrada.marca_dagua) : '';
  // colchetes "[... reserved for the accountant's text]" so em teste ou com marca d'agua; na invoice real,
  // sem o texto cadastrado, a linha sai omitida (ou o resumo bloqueia, com bloquear_sem_texto_contador)
  var reservar = cfgBool(cfg.espacos_reservados_contador) && (teste || !!marca);
  // SKU no PDF do cliente: 'sku' (padrao) | 'ref' (rotulo neutro) | 'nao' (so no resumo e no snapshot)
  var modoSku = String(cfg.sku_no_pdf || 'sku').trim().toLowerCase();
  var doc = {
    teste: teste, marca_dagua: marca,
    faixa_texto: (marca || 'TEST') + ' · NOT A VALID INVOICE · NO TAX OR PAYMENT VALUE',
    numero: numero, emitida: fmtData(entrada.emitida_em), validade: validade,
    preparado_por: L(entrada.solicitante_nome || 'Horizon'),
    empresa_linha: L(cfg.empresa_linha || 'HORIZON DECOR LLC · Florida, USA · horizongroupamericas.com'),
    tagline: L(cfg.tagline || ''), rodape: L(cfg.rodape || ''),
    bill_to: [
      { campo: 'nome', texto: L(c.cliente.nome) }, { campo: 'empresa', texto: L(c.cliente.empresa) },
      { campo: 'e-mail', texto: L(c.cliente.email) }, { campo: 'telefone', texto: L(c.cliente.telefone) },
      { campo: 'certificado', texto: c.isento && entrada.certificado_revenda ? 'FL resale cert. ' + L(entrada.certificado_revenda) : '' }
    ].filter(function (x) { return x.texto; }),
    deliver_to: [
      { campo: 'endereço', texto: L(c.entrega.endereco), linhas: 2 },
      { campo: 'cidade', texto: [L(c.entrega.cidade), 'FL' + (c.entrega.zip ? ' ' + c.entrega.zip : '')].filter(Boolean).join(', ') },
      { campo: 'condado', texto: L(cond.nome) + ' County' }
    ].filter(function (x) { return x.texto; }),
    detalhes: [['Issued', fmtData(entrada.emitida_em)], ['Valid until', validade], ['Terms', 'Due on receipt'], ['Currency', 'USD']],
    itens: [], extras: [], resumo: [], pagamento: [], referencia: 'Please reference ' + numero + ' with your payment.', condicoes: [],
    selo: String(cfg.selo_foto || 'Manufacturer photo').split(' · ').map(L).filter(Boolean),
    com_desconto: c.itens.some(function (l) { return (l.desconto_cents || 0) > 0; })
  };
  var imgs = { logo: { b64: entrada.logo_b64 }, fotos: [] };
  var fotoModelo = false, snapshot = [];
  c.itens.forEach(function (l) {
    var f = l.foto && entrada.fotos ? entrada.fotos[l.sku] : null, idx = null, modelo = false;
    if (f && f.b64) { idx = imgs.fotos.length; imgs.fotos.push({ b64: f.b64 }); if (l.foto.origem === 'modelo') { fotoModelo = true; modelo = true; } }
    snapshot.push(Object.assign({}, l, { foto_url: idx !== null ? (f.url || l.foto.url) : null, foto_sha256: idx !== null ? (f.sha256 || l.foto.sha256 || null) : null }));
    var titulo = l.produto === 'Bali' ? 'Bali sculpture' : (l.produto === 'Ori' ? 'Ori vases (set of 2)' : l.produto + ' vase');
    doc.itens.push({
      titulo: L(titulo),
      detalhe: L(l.colecao + ' Collection' + (l.acabamento ? ' · Finish: ' + l.acabamento : '') + ' · ' + (l.tamanho ? 'Size: ' + l.tamanho : 'One size')),
      sku: modoSku === 'nao' ? '' : L((modoSku === 'ref' ? 'Ref. ' : 'SKU ') + l.sku),
      medidas: L(l.medidas_txt || 'Dimensions on request'), medidas_pendente: !l.medidas_txt,
      // foto do modelo (nao da variante): o aviso fica na propria linha, nao so nas condicoes
      nota_foto: modelo ? 'Photo shows the model; finish/size may differ' : '',
      qtd: String(l.qtd), unit: fmtUSD(l.preco_unit_cents),
      desconto: l.desconto_cents ? '-' + fmtUSD(l.desconto_cents) : '—',
      desconto_sub: l.desconto_cents && l.desconto_pct_bp ? fmtPct(l.desconto_pct_bp) + ' off' : '',
      total: fmtUSD(l.total_cents), foto: idx
    });
  });
  var f = c.frete;
  // texto do frete sem depender da posicao (a linha pode cair numa pagina de continuacao)
  var destinoFrete = 'To the delivery address (' + [L(c.entrega.cidade), 'FL' + (c.entrega.zip ? ' ' + c.entrega.zip : '')].filter(Boolean).join(', ') + ')';
  if (f.status === 'a_cotar') doc.extras.push({ titulo: 'Freight', sub: 'To be quoted separately (not included in the total)', qtd: '—', unit: '—', desconto: '—', total: '—' });
  else if (f.status === 'gratis') doc.extras.push({ titulo: 'Freight', sub: 'No charge · ' + destinoFrete, qtd: '1', unit: '$0.00', desconto: '—', total: '$0.00' });
  else if (f.status === 'cortesia') doc.extras.push({ titulo: 'Freight', sub: 'Complimentary delivery · ' + destinoFrete, qtd: '1', unit: '$0.00', desconto: '—', total: '$0.00' });
  else doc.extras.push({ titulo: f.tributavel ? 'Freight (separately stated, taxable)' : 'Freight (separately stated)', sub: destinoFrete, qtd: '1', unit: fmtUSD(f.cents), desconto: '—', total: fmtUSD(f.cents) });
